// ServerInterface represents all server handlers.
type ServerInterface interface {
	// CompleteLogin Redirect target registered in authentik; finishes the sign-in
	// (GET /auth/callback)
	CompleteLogin(w http.ResponseWriter, r *http.Request, params CompleteLoginParams)
	// CompleteHomeConnection Redirect target of Home Assistant's sign-in; connects the caller
	// (GET /auth/homeassistant/callback)
	CompleteHomeConnection(w http.ResponseWriter, r *http.Request, params CompleteHomeConnectionParams)
	// StartLogin Start the sign-in at authentik (browser navigation, not fetch)
	// (GET /auth/login)
	StartLogin(w http.ResponseWriter, r *http.Request)
	// Logout End the session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request, params LogoutParams)
	// GetHealth Liveness probe
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetReadiness Readiness probe (checks Postgres and Redis)
	// (GET /readyz)
	GetReadiness(w http.ResponseWriter, r *http.Request)
	// GetCalendar The iCalendar feed behind a subscription link
	// (GET /v1/calendar-feeds/{token})
	GetCalendar(w http.ResponseWriter, r *http.Request, token string)
	// DeleteConversation Delete one of your conversations
	// (DELETE /v1/conversations/{conversationId})
	DeleteConversation(w http.ResponseWriter, r *http.Request, conversationId ConversationId)
	// GetConversation One of your conversations with its last 40 messages, oldest first
	// (GET /v1/conversations/{conversationId})
	GetConversation(w http.ResponseWriter, r *http.Request, conversationId ConversationId)
	// DeleteEntry Delete an entry (same rules as changing it)
	// (DELETE /v1/entries/{entryId})
	DeleteEntry(w http.ResponseWriter, r *http.Request, entryId EntryId)
	// GetEntry One entry
	// (GET /v1/entries/{entryId})
	GetEntry(w http.ResponseWriter, r *http.Request, entryId EntryId)
	// UpdateEntry Change an entry
	// (PUT /v1/entries/{entryId})
	UpdateEntry(w http.ResponseWriter, r *http.Request, entryId EntryId)
	// ReopenEntry Untick a reminder
	// (DELETE /v1/entries/{entryId}/done)
	ReopenEntry(w http.ResponseWriter, r *http.Request, entryId EntryId)
	// CompleteEntry Tick off a reminder
	// (PUT /v1/entries/{entryId}/done)
	CompleteEntry(w http.ResponseWriter, r *http.Request, entryId EntryId)
	// GetGuestCall Who invited the holder of a guest link (no sign-in)
	// (GET /v1/guest-calls/{token})
	GetGuestCall(w http.ResponseWriter, r *http.Request, token string)
	// JoinGuestCall Join a call through a guest link (no sign-in)
	// (POST /v1/guest-calls/{token})
	JoinGuestCall(w http.ResponseWriter, r *http.Request, token string)
	// ListHouseholds Households the current user belongs to
	// (GET /v1/households)
	ListHouseholds(w http.ResponseWriter, r *http.Request)
	// CreateHousehold Create a household; the caller becomes its owner
	// (POST /v1/households)
	CreateHousehold(w http.ResponseWriter, r *http.Request)
	// GetHousehold One household with its members (members only)
	// (GET /v1/households/{householdId})
	GetHousehold(w http.ResponseWriter, r *http.Request, householdId openapi_types.UUID)
	// DeleteCalendarFeed Turn your calendar subscription link off
	// (DELETE /v1/households/{householdId}/calendar-feed)
	DeleteCalendarFeed(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// GetCalendarFeed Whether you have a calendar subscription link
	// (GET /v1/households/{householdId}/calendar-feed)
	GetCalendarFeed(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// CreateCalendarFeed Make a calendar subscription link; an earlier one stops working
	// (POST /v1/households/{householdId}/calendar-feed)
	CreateCalendarFeed(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// CreateCalendarProfile Make a calendar password and an iPhone profile that adds it as a CalDAV account
	// (POST /v1/households/{householdId}/calendar-profile)
	CreateCalendarProfile(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// StartCall Start a voice and video call with other members (members only)
	// (POST /v1/households/{householdId}/calls)
	StartCall(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// TalkToHomeloom Start a voice call with Homeloom (members only)
	// (POST /v1/households/{householdId}/calls/homeloom)
	TalkToHomeloom(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// CreateGuestLink Make a link that lets someone without an account into the call (members only)
	// (POST /v1/households/{householdId}/calls/{callId}/guest-links)
	CreateGuestLink(w http.ResponseWriter, r *http.Request, householdId HouseholdId, callId CallId)
	// InviteToCall Ring more members into a call (members only)
	// (POST /v1/households/{householdId}/calls/{callId}/invites)
	InviteToCall(w http.ResponseWriter, r *http.Request, householdId HouseholdId, callId CallId)
	// JoinCall Join or answer one of the household's calls (members only)
	// (POST /v1/households/{householdId}/calls/{callId}/join)
	JoinCall(w http.ResponseWriter, r *http.Request, householdId HouseholdId, callId CallId)
	// Chat Ask the assistant; the answer streams back as server-sent events
	// (POST /v1/households/{householdId}/chat)
	Chat(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ListConversations Your chats with the assistant in this household, last used first
	// (GET /v1/households/{householdId}/conversations)
	ListConversations(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// SuggestRecipes Pick recipes from Mealie that fit a mood (members only)
	// (POST /v1/households/{householdId}/cook/suggestions)
	SuggestRecipes(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ListEntries Calendar events, notes and reminders you can see (members only)
	// (GET /v1/households/{householdId}/entries)
	ListEntries(w http.ResponseWriter, r *http.Request, householdId HouseholdId, params ListEntriesParams)
	// CreateEntry Write a note, set a reminder or add a calendar event
	// (POST /v1/households/{householdId}/entries)
	CreateEntry(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// GetHome Rooms, scenes, lights and readings from Home Assistant, read live (members only)
	// (GET /v1/households/{householdId}/home)
	GetHome(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// DisconnectHome Disconnect your Home Assistant account and revoke its token
	// (DELETE /v1/households/{householdId}/home/connection)
	DisconnectHome(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ConnectHome Start connecting your Home Assistant account
	// (POST /v1/households/{householdId}/home/connection)
	ConnectHome(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ToggleLight Switch a light on or off
	// (POST /v1/households/{householdId}/home/lights/{lightId}/toggle)
	ToggleLight(w http.ResponseWriter, r *http.Request, householdId HouseholdId, lightId string)
	// ActivateScene Turn a scene on
	// (POST /v1/households/{householdId}/home/scenes/{sceneId})
	ActivateScene(w http.ResponseWriter, r *http.Request, householdId HouseholdId, sceneId string)
	// CreateInvite Create a one-time invite link code (members only)
	// (POST /v1/households/{householdId}/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ListMcpTokens Your keys and passwords for other apps
	// (GET /v1/households/{householdId}/mcp-tokens)
	ListMcpTokens(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// CreateMcpToken Make a key or password for another app
	// (POST /v1/households/{householdId}/mcp-tokens)
	CreateMcpToken(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ListQuestions The household's questions, newest first (members only)
	// (GET /v1/households/{householdId}/questions)
	ListQuestions(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// AskQuestion Ask the household a question
	// (POST /v1/households/{householdId}/questions)
	AskQuestion(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// GetRecipe A recipe from Mealie with its ingredients and steps (members only)
	// (GET /v1/households/{householdId}/recipes/{slug})
	GetRecipe(w http.ResponseWriter, r *http.Request, householdId HouseholdId, slug RecipeSlug)
	// ListShoppingItems The household's shared shopping list (members only)
	// (GET /v1/households/{householdId}/shopping-list)
	ListShoppingItems(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// AddToShoppingList Put a recipe's missing ingredients on the household's shopping list (members only)
	// (POST /v1/households/{householdId}/shopping-list)
	AddToShoppingList(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// ClearShoppingItems Remove every ticked item
	// (DELETE /v1/households/{householdId}/shopping-list/done)
	ClearShoppingItems(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// AddShoppingItem Put something on the shopping list
	// (POST /v1/households/{householdId}/shopping-list/items)
	AddShoppingItem(w http.ResponseWriter, r *http.Request, householdId HouseholdId)
	// DeleteShoppingItem Take an item off the list
	// (DELETE /v1/households/{householdId}/shopping-list/items/{itemId})
	DeleteShoppingItem(w http.ResponseWriter, r *http.Request, householdId HouseholdId, itemId ShoppingItemId)
	// UntickShoppingItem Untick an item
	// (DELETE /v1/households/{householdId}/shopping-list/items/{itemId}/done)
	UntickShoppingItem(w http.ResponseWriter, r *http.Request, householdId HouseholdId, itemId ShoppingItemId)
	// TickShoppingItem Tick an item off
	// (PUT /v1/households/{householdId}/shopping-list/items/{itemId}/done)
	TickShoppingItem(w http.ResponseWriter, r *http.Request, householdId HouseholdId, itemId ShoppingItemId)
	// AcceptInvite Join the household an invite belongs to
	// (POST /v1/invites/{code})
	AcceptInvite(w http.ResponseWriter, r *http.Request, code string)
	// DeleteMcpToken Delete one of your tokens; the app loses access at once
	// (DELETE /v1/mcp-tokens/{tokenId})
	DeleteMcpToken(w http.ResponseWriter, r *http.Request, tokenId openapi_types.UUID)
	// GetMe The signed-in user, created on first call
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// GetVoice How Homeloom sounds on the caller's calls with it
	// (GET /v1/me/voice)
	GetVoice(w http.ResponseWriter, r *http.Request)
	// SaveVoice Save how Homeloom sounds on the caller's calls with it
	// (PUT /v1/me/voice)
	SaveVoice(w http.ResponseWriter, r *http.Request)
	// PreviewVoice Hear a short sentence spoken with the given settings
	// (POST /v1/me/voice/preview)
	PreviewVoice(w http.ResponseWriter, r *http.Request)
	// GetPushConfig The VAPID public key to subscribe with
	// (GET /v1/push)
	GetPushConfig(w http.ResponseWriter, r *http.Request)
	// UnsubscribePush Stop notifications on this device
	// (DELETE /v1/push/subscriptions)
	UnsubscribePush(w http.ResponseWriter, r *http.Request, params UnsubscribePushParams)
	// SubscribePush Get notifications on this device
	// (POST /v1/push/subscriptions)
	SubscribePush(w http.ResponseWriter, r *http.Request)
	// AnswerQuestion Write or change your answer; the question opens once every member has answered
	// (PUT /v1/questions/{questionId}/answer)
	AnswerQuestion(w http.ResponseWriter, r *http.Request, questionId openapi_types.UUID)
}

